    imageHint: "Maasi Order Castle ruins Saaremaa",
    descriptionAdvanced: {
      de: "Die Ruinen der Ordensburg Maasi, auch Maasilinn genannt, befinden sich auf der Insel Saaremaa und zeugen von der wechselvollen mittelalterlichen Geschichte Estlands. Die Burg wurde 1345 vom Livländischen Orden als Ersatz für die im Aufstand der Georgsnacht zerstörte Burg Pöide errichtet. Maasi diente als Sitz eines Vogts und sollte die Kontrolle über den strategisch wichtigen Seeweg zwischen den Inseln und dem Festland sichern. Im Gegensatz zu vielen anderen estnischen Burgen wurde Maasi 1576 auf Befehl des dänischen Königs Friedrich II. gesprengt, um zu verhindern, dass sie in feindliche Hände fällt. Über Jahrhunderte lagen die Überreste unter Trümmern begraben, bis Ausgrabungen in den 1990er Jahren das gut erhaltene Erdgeschoss und beeindruckende Gewölbe freilegten. Heute ist die Stätte für Besucher zugänglich und bietet einen authentischen Einblick in die Wehrarchitektur des 14. Jahrhunderts, ohne durch moderne Rekonstruktionen verfälscht zu sein.",
      hu: "Maasi rendi várának romjai, más néven Maasilinn, Saaremaa szigetén találhatók, és Észtország fordulatos középkori történelmének tanúi. A várat 1345-ben építette a Livóniai Rend, hogy felváltsa a Szent György-éji felkelés során elpusztult Pöide várát. Maasi egy tiszttartó (vogt) székhelyeként szolgált, és célja a szigetek és a szárazföld közötti stratégiai fontosságú tengeri útvonal ellenőrzése volt. Sok más észt várral ellentétben Maasi-t 1576-ban II. Frigyes dán király parancsára felrobbantották, hogy megakadályozzák ellenséges kézre kerülését. A maradványok évszázadokon át törmelék alatt pihentek, amíg az 1990-es években végzett ásatások során fel nem tárták a meglepően jó állapotban maradt földszintet és a lenyűgöző boltíveket. Ma a helyszín látogatható, és hiteles betekintést nyújt a 14. századi katonai építészetbe, anélkül, hogy modern rekonstrukciók elfednék az eredeti részleteket.",
      ro: "Ruinele castelului ordinului Maasi, cunoscut și sub numele de Maasilinn, se află pe insula Saaremaa și depun mărturie despre istoria medievală zbuciumată a Estoniei. Castelul a fost ridicat în 1345 de Ordinul Livonian pentru a înlocui castelul Pöide, distrus în timpul răscoalei din Noaptea Sfântului Gheorghe. Maasi a servit drept sediu al unui pârcălab și avea rolul de a asigura controlul asupra rutei maritime strategice dintre insule și continent. Spre deosebire de multe alte castele estoniene, Maasi a fost aruncat în aer în 1576 la ordinul regelui danez Frederic al II-lea, pentru a preveni căderea sa în mâini inamice. Timp de secole, vestigiile au rămas îngropate sub dărâmături, până când excavațiile din anii 1990 au scos la lumină parterul bine conservat și bolțile impresionante. Astăzi, situl este deschis vizitatorilor, oferind o perspectivă autentică asupra arhitecturii defensive din secolul al XIV-lea.",
      en: "The ruins of Maasi Order Castle, also known as Maasilinn, are located on the island of Saaremaa and stand as a testament to Estonia's turbulent medieval history. The fortress was constructed in 1345 by the Livonian Order to replace the Pöide Castle, which had been destroyed during the St. George's Night Uprising. Maasi served as the seat of a bailiff (vogt) and was designed to maintain control over the strategically vital maritime route between the islands and the mainland. Unlike many other Estonian castles, Maasi was intentionally blown up in 1576 by order of the Danish King Frederick II to prevent it from falling into enemy hands. For centuries, the remains lay buried under debris until archaeological excavations in the 1990s revealed the well-preserved ground floor and impressive vaulted ceilings. Today, the site is open to the public, offering an authentic glimpse into 14th-century defensive architecture without modern reconstructions.",
      es: "Las ruinas del castillo de la orden Maasilinna datan del año 1345. La fortaleza fue construida después del Levantamiento de la Noche de San Jorge para sustituir al destruido castillo de Pöide.",
      pt: "As ruínas do castelo da ordem Maasilinna datam do ano de 1345. A fortaleza foi construída após a Revolta da Noite de São Jorge como substituta para o castelo de Pöide destruído.",
      fr: "Les ruines du château de l'ordre Maasilinna datent de l'année 1345. La forteresse fut érigée après le soulèvement de la nuit de la Saint-Georges pour remplacer le château détruit de Pöide.",
    },
