      de: "Die Burg Kastre war eine bischöfliche Festung am Fluss Emajõgi. Sie diente im Mittelalter zur Kontrolle der Wasserwege in der Nähe von Tartu.",
      hu: "A Kastre vár egy püspöki erődítmény volt az Emajõgi folyó mentén. A középkorban a Tartú környéki vízi utak ellenőrzésére szolgált.",
      ro: "Castelul Kastre a fost o fortăreață episcopală de pe râul Emajõgi. În Evul Mediu, a servit la controlul căilor navigabile din apropierea orașului Tartu.",
      en: "Kastre Castle was an episcopal fortress located on the Emajõgi River. In the Middle Ages, it served to control waterways near Tartu.",
