    imageHint: "Kastre castle ruins Emajogi river",
    descriptionAdvanced: {
      de: "Die Überreste der Burg Kastre liegen strategisch günstig am Fluss Emajõgi und dienten im Mittelalter als wichtige Zollstation und Verteidigungsanlage. Die erste urkundliche Erwähnung der Anlage als bischöfliche Burg stammt aus dem 14. Jahrhundert. Kastre kontrollierte den gesamten Schiffsverkehr zwischen dem Peipussee und der Stadt Tartu, was ihr eine enorme wirtschaftliche Bedeutung verlieh. Während des Livländischen Krieges und später im Großen Nordischen Krieg war die Burg Schauplatz heftiger Kämpfe. Im Jahr 1704 fand in der Nähe die entscheidende Seeschlacht am Emajõgi statt, bei der die schwedische Flotte von den russischen Truppen vernichtet wurde. Die Burg wurde dabei weitgehend zerstört und verfiel in den folgenden Jahrhunderten. Heute sind nur noch geringe Mauerreste und Erdwälle sichtbar, die jedoch ein wichtiges archäologisches Denkmal für die Sicherung der estnischen Wasserstraßen darstellen.",
      hu: "Kastre várának maradványai stratégiai szempontból fontos helyen, az Emajõgi-folyó partján fekszenek, és a középkorban jelentős vámszedő helyként és védelmi létesítményként szolgáltak. A püspöki vár első írásos említése a 14. századból származik. Kastre ellenőrizte a Csúd-tó és Tartu városa közötti teljes hajóforgalmat, ami hatalmas gazdasági jelentőséget kölcsönzött neki. A livóniai háború, majd később a nagy északi háború idején a vár heves harcok színhelye volt. 1704-ben a közelben zajlott le a döntő jelentőségű emajõgi folyami csata, amelyben az orosz csapatok megsemmisítették a svéd flottát. A vár ekkor nagyrészt elpusztult, és a következő évszázadokban romlásnak indult. Ma már csak csekély falmaradványok és földsáncok láthatók, amelyek azonban fontos régészeti emlékei az észt vízi utak egykori biztosításának.",
      ro: "Vestigiile castelului Kastre sunt situate strategic pe malul râului Emajõgi, servind în Evul Mediu drept un important punct vamal și fortificație defensivă. Prima mențiune documentară a așezării ca și castel episcopal datează din secolul al XIV-lea. Kastre controla întregul trafic naval între Lacul Peipus și orașul Tartu, ceea ce îi conferea o importanță economică enormă. În timpul Războiului Livonian și, mai târziu, în Marele Război al Nordului, castelul a fost scena unor lupte crâncene. În anul 1704, în apropiere a avut loc bătălia navală decisivă de pe Emajõgi, în care flota suedeză a fost distrusă de trupele ruse. Castelul a fost în mare parte distrus atunci și s-a ruinat în secolele următoare. Astăzi, mai sunt vizibile doar câteva fragmente de ziduri și valuri de pământ, care reprezintă însă un monument arheologic important pentru securizarea căilor navigabile estoniene.",
      en: "The remains of Kastre Castle are strategically situated on the banks of the Emajõgi River, having served as a vital toll station and defensive fortification during the Middle Ages. First documented in the 14th century as a bishop's castle, Kastre controlled all maritime traffic between Lake Peipus and the city of Tartu, granting it immense economic significance. Throughout the Livonian War and later the Great Northern War, the castle was the site of fierce military engagements. In 1704, the decisive naval Battle of Emajõgi took place nearby, where the Swedish flotilla was decimated by Russian forces. The castle was largely destroyed during this conflict and fell into ruin in the subsequent centuries. Today, only minor wall fragments and earthworks remain visible, yet they constitute an important archaeological site reflecting the historical protection of Estonia's inland waterways.",
      es: "El castillo de Kastre (también conocido como Warbeck) es un castillo episcopal medieval en el sur de Estonia, construido en el siglo XIV sobre una colina artificial. El castillo sirvió a los obispos de Dorpat como centro administrativo y defensivo. Su arquitectura muestra el diseño típico de un castillo de la orden con planta rectangular y patio central. En el siglo XVI sufrió graves daños durante la Guerra de Livonia. En el siglo XVII pasó a manos de Suecia. Hoy solo se conservan ruinas protegidas por una cubierta. El lugar es un destino popular de excursiones y se utiliza para festivales históricos.",
      pt: "O castelo de Kastre (também conhecido como Warbeck) é um castelo episcopal medieval no sul da Estónia, construído no século XIV numa colina artificial. O castelo serviu os bispos de Dorpat como centro administrativo e defensivo. A sua arquitetura mostra um castelo de ordem típico com uma planta retangular e um pátio central. No século XVI, foi gravemente danificado durante a Guerra da Livónia. No século XVII, passou para a Suécia. Hoje restam apenas ruínas, protegidas por uma cobertura. O local é um destino popular de excursões e é usado para festivais históricos.",
      fr: "Le château de Kastre (également connu sous le nom de Warbeck) est un château épiscopal médiéval du sud de l'Estonie, construit au XIVe siècle sur une colline artificielle. Le château servait aux évêques de Dorpat de centre administratif et défensif. Son architecture présente un château de l'ordre typique avec un plan rectangulaire et une cour centrale. Au XVIe siècle, il a été gravement endommagé pendant la guerre de Livonie. Au XVIIe siècle, il est tombé aux mains de la Suède. Aujourd'hui, il ne reste que des ruines protégées par un toit. Le site est une destination d'excursion populaire et est utilisé pour des fêtes historiques.",
    },
