      es: ["Fundado en el año 1417.", "Parte de la orden de las Brigidinas.", "Los muros de la iglesia miden 24 metros de altura.", "Destruido en la Guerra de Livonia en 1577.", "La superficie interior de la iglesia es de 1360 metros cuadrados.", "Excavado en la década de 1970."],
      pt: ["Fundado no ano de 1417.", "Parte da ordem de Santa Brígida.", "As paredes da igreja medem 24 metros de altura.", "Destruído na Guerra da Livônia em 1577.", "A área interior da igreja é de 1360 metros quadrados.", "Escavado na década de 1970."],
      fr: ["Fondé en 1417.", "Fait partie de l'ordre de Sainte-Brigitte.", "Les murs de l'église mesurent 24 mètres de hauteur.", "Détruit lors de la guerre de Livonie en 1577.", "La surface intérieure de l'église est de 1360 mètres carrés.", "Fouilles effectuées dans les années 1970."],
