    imageHint: "Keila-Joa manor ruins",
    descriptionAdvanced: {
      de: "Das Schloss Keila-Joa, auch als Schloss Fall bekannt, ist eines der prächtigsten Beispiele neugotischer Architektur in Estland. Es wurde 1833 für den Grafen Alexander von Benckendorff, den Begründer des russischen Geheimdienstes, nach Plänen des Architekten Hans von Stackenschneider errichtet. Die Lage direkt am Keila-Wasserfall, dem dritthöchsten Wasserfall Estlands, verleiht dem Anwesen eine außergewöhnliche landschaftliche Dramatik. Das Schloss diente im 19. Jahrhundert als Treffpunkt der russischen Elite und wurde von namhaften Persönlichkeiten wie Zar Nikolaus I. besucht. Nach einer langen Zeit des Verfalls in der sowjetischen Ära, als das Gebäude militärisch genutzt wurde, erfolgte ab 2010 eine umfassende und detailgetreue Restaurierung durch private Investoren. Heute beherbergt das Schloss ein Museum, ein Boutique-Hotel und ein Restaurant. Der umliegende Park mit seinen historischen Brücken lädt zu Erkundungen der umliegenden Natur und der Schlossruinen ein.",
      hu: "A keila-joai kastély, más néven Schloss Fall, az észtországi neogótikus építészet egyik legpompásabb példája. 1833-ban épült Alexander von Benckendorff gróf, az orosz titkosszolgálat alapítója számára, Hans von Stackenschneider építész tervei alapján. A kastély elhelyezkedése közvetlenül a Keila-vízesésnél, Észtország harmadik legmagasabb vízesésénél, rendkívüli táji drámaiságot kölcsönöz az ingatlannak. A 19. században a kastély az orosz elit találkozóhelyeként szolgált, és olyan neves személyiségek látogatták meg, mint I. Miklós cár. A szovjet korszakban bekövetkezett hosszú hanyatlás után, amikor az épületet katonai célokra használták, 2010-től magánbefektetők révén átfogó és részlethű restauráláson esett át. Ma a kastély múzeumnak, egy butikhotelnek és egy étteremnek ad otthont. A környező park a történelmi hídjaival kiváló lehetőséget nyújt a természet és a kastély körüli romok felfedezésére.",
      ro: "Castelul Keila-Joa, cunoscut și sub numele de Schloss Fall, este unul dintre cele mai splendide exemple de arhitectură neogotică din Estonia. A fost construit în 1833 pentru contele Alexander von Benckendorff, fondatorul serviciului secret rus, după planurile arhitectului Hans von Stackenschneider. Locația sa direct lângă cascada Keila, a treia ca înălțime din Estonia, conferă domeniului o dramaticitate peisagistică extraordinară. În secolul al XIX-lea, castelul a servit drept loc de întâlnire pentru elita rusă, fiind vizitat de personalități marcante precum țarul Nicolae I. După o lungă perioadă de degradare în epoca sovietică, când clădirea a fost utilizată de armată, a urmat din 2010 o restaurare amplă și fidelă detaliilor realizată de investitori privați. Astăzi, castelul găzduiește un muzeu, un hotel boutique și un restaurant. Parcul înconjurător cu podurile sale istorice invită la explorarea naturii și a vestigiilor castelului.",
      en: "Keila-Joa Castle, historically known as Schloss Fall, is one of the most magnificent examples of Neo-Gothic architecture in Estonia. Built in 1833 for Count Alexander von Benckendorff, the founder of the Russian secret police, it was designed by the renowned architect Hans von Stackenschneider. Its location adjacent to the Keila Waterfall—the third highest in Estonia—provides a dramatic natural backdrop to the estate. During the 19th century, the castle served as a prestigious gathering place for the Russian elite and was visited by prominent figures including Tsar Nicholas I. After decades of neglect during the Soviet era, when the building was used by the military, a comprehensive and meticulous restoration was initiated by private investors in 2010. Today, the manor functions as a museum, boutique hotel, and restaurant. The expansive surrounding park, featuring historical bridges, offers scenic trails through the local landscape and the ruins of auxiliary estate buildings.",
      es: "El palacio Schloss Fall fue erigido en 1833 en estilo neogótico para el conde Alexander von Benckendorff. Se considera una de las primeras obras neogóticas importantes del Báltico.",
      pt: "O Palácio Schloss Fall foi erguido em 1833 em estilo neogótico para o Conde Alexander von Benckendorff. É considerado uma das primeiras obras neogóticas importantes nos países bálticos.",
      fr: "Le château Fall a été érigé en 1833 dans le style néogothique pour le comte Alexandre de Benckendorff. Il est considéré comme l'un des premiers édifices néogothiques majeurs des pays baltes.",
    },
    factsAdvanced: {
      de: ["Schloss wurde im Jahr 1833 fertiggestellt", "Architekt war der berühmte Hans von Stackenschneider", "Liegt am 6 Meter hohen Keila-Wasserfall", "Benannt nach dem deutschen Namen 'Schloss Fall'", "Zar Nikolaus I. war ein Gast bei der Einweihung", "Umfassende Restaurierung begann im Jahr 2010"],
      hu: ["A kastély 1833-ban készült el", "Az építész a híres Hans von Stackenschneider volt", "A 6 méter magas Keila-vízesés mellett található", "Német neve után 'Schloss Fall'-ként is ismerik", "I. Miklós cár is vendég volt a felszenteléskor", "Az átfogó restaurálás 2010-ben kezdődött"],
      ro: ["Castelul a fost finalizat în anul 1833", "Arhitectul a fost celebrul Hans von Stackenschneider", "Situat lângă cascada Keila, înaltă de 6 metri", "Cunoscut sub numele german de 'Schloss Fall'", "Țarul Nicolae I a fost oaspete la inaugurare", "Restaurarea completă a început în anul 2010"],
      en: ["The castle was completed in the year 1833", "Designed by the famous architect Hans von Stackenschneider", "Located by the 6-meter-high Keila Waterfall", "Known by its German name 'Schloss Fall'", "Tsar Nicholas I attended the castle's inauguration", "Extensive restoration project began in 2010"],
      es: ["Finalización en 1833", "Cascada de 6 metros de altura al lado", "Arquitecto: Hans von Stackenschneider", "Restauración en el año 2013"],
      pt: ["Conclusão em 1833", "Cascata de 6 metros de altura ao lado", "Arquiteto: Hans von Stackenschneider", "Restauro no ano de 2013"],
      fr: ["Achèvement en 1833", "Cascade de 6 mètres de haut juste à côté", "Architecte : Hans von Stackenschneider", "Restauration en 2013"],
    },
