      hu: ["A főépület építése 1890-ben kezdődött és 1892-ben fejeződött be", "Az építészeti stílus a romantikus neogótika jegyeit hordozza", "Az építtető Woldemar von Uexküll báró volt", "Az 1919-es földreform során vették állami tulajdonba", "A szovjet korszakban rádióállomás működött a falai között", "Jelenleg szállodaként és rendezvényközpontként üzemel"],
      ro: ["Construcția clădirii principale a durat între 1890 și 1892", "Stilul arhitectural este neogotic, imitând castelele medievale", "Proprietarul care a ridicat conacul a fost Woldemar von Uexküll", "Proprietatea a fost naționalizată în urma reformei din 1919", "A fost utilizat ca stație radio în timpul perioadei sovietice", "Funcționează în prezent ca hotel boutique și restaurant de lux"],
