    imageHint: "Sangaste castle manor",
    descriptionAdvanced: {
      de: "Schloss Sangaste, im Süden Estlands gelegen, ist eines der beeindruckendsten Zeugnisse des Historismus im Baltikum. Das zwischen 1874 und 1881 errichtete Gebäude wurde vom Architekten Otto Pius Hippius im Auftrag des Grafen Friedrich Georg Magnus von Berg entworfen. Als Inspiration diente das englische Windsor Castle, was sich in der prachtvollen neugotischen Architektur mit roten Backsteinen, zahlreichen Türmen und Erkern widerspiegelt. Graf von Berg, ein bekannter Roggenzüchter, wollte ein Anwesen schaffen, das sowohl repräsentativ als auch modern war. Das Schloss verfügte bereits früh über technische Neuerungen wie eine Zentralheizung und Telefonanschlüsse. Der Festsaal und die Bibliothek sind bis heute für ihre prächtige Innenausstattung bekannt, die den Reichtum des Adels im 19. Jahrhundert unterstreicht. Umgeben ist das Schloss von einem weitläufigen Dendropark mit seltenen Baumarten aus aller Welt. Heute wird das Gebäude als Hotel und Veranstaltungsort genutzt und ist eng mit der Geschichte der estnischen Landwirtschaft und der Roggensorte 'Sangaste' verbunden.",
      hu: "A Dél-Észtországban található Sangaste-kastély a balti historizáló építészet egyik legpompásabb alkotása. Az 1874 és 1881 között épült kastélyt Otto Pius Hippius építész tervezte Friedrich Georg Magnus von Berg gróf megbízásából. Az épület mintájául az angol Windsori kastély szolgált, ami megmutatkozik a vörös téglás homlokzaton, a számos tornyon és a neogótikus stíluselemeken. Von Berg gróf, aki neves rozsnemesítő volt, nemcsak egy reprezentatív lakóhelyet, hanem egy modern gazdasági központot is létrehozott. A kastély már a korai időkben rendelkezett központi fűtéssel és telefonnal, ami akkoriban ritkaságnak számított. A belső terek közül kiemelkedik a díszterem és a könyvtár, amelyek ma is eredeti pompájukban csodálhatók meg. A kastélyt egy hatalmas dendropark veszi körül, ahol a világ minden tájáról származó ritka fafajok találhatók. Jelenleg szállodaként és kulturális központként működik, és szorosan kötődik az észt mezőgazdaság történetéhez és a híres 'Sangaste' rozsfajtához.",
      ro: "Castelul Sangaste, situat în sudul Estoniei, este unul dintre cele mai impresionante exemple de arhitectură istoricistă din regiunea baltică. Construit între 1874 și 1881, castelul a fost proiectat de arhitectul Otto Pius Hippius pentru contele Friedrich Georg Magnus von Berg. Sursa de inspirație a fost Castelul Windsor din Anglia, fapt vizibil în utilizarea cărămizii roșii, a numeroaselor turnuri și a elementelor decorative neogotice. Contele von Berg, un renumit ameliorator de secară, a dorit să creeze o reședință care să combine luxul aristocratic cu inovația tehnică a vremii. Astfel, castelul a fost dotat timpuriu cu încălzire centrală și telefon. Interiorul este celebru pentru sala de bal și biblioteca sa fastuoasă, care reflectă gusturile rafinate ale secolului al XIX-lea. Proprietatea este înconjurată de un parc dendrologic vast, care adăpostește specii rare de arbori aduse din întreaga lume. Astăzi, castelul servește drept hotel și centru pentru evenimente, fiind un simbol al moștenirii agricole estone prin legătura sa cu soiul de secară 'Sangaste'.",
      en: "Sangaste Castle, located in southern Estonia, is one of the most magnificent examples of historicist architecture in the Baltic states. Built between 1874 and 1881, the castle was designed by architect Otto Pius Hippius for Count Friedrich Georg Magnus von Berg. The design was famously inspired by Windsor Castle in England, which is evident in its red-brick exterior, numerous towers, and elaborate Neo-Gothic details. Count von Berg, a prominent rye breeder, intended the estate to be both a grand residence and a modern agricultural hub. Remarkably, the castle featured early technological innovations such as central heating and a telephone system shortly after its completion. The interior highlights include the grand ballroom and the library, which showcase the opulence of the late 19th-century nobility. The castle is surrounded by an extensive dendropark featuring rare tree species collected from across the globe. Today, it operates as a hotel and venue, remaining closely linked to Estonian agricultural history and the famous 'Sangaste' rye variety.",
      es: "El castillo de Sangaste (también llamado Sagnitz) es una mansión neogótica en el sur de Estonia, construida entre 1873 y 1879 para el conde Friedrich von Berg. El castillo es conocido por su torre de 50 metros de altura y su rica decoración interior con trofeos de caza y tallas de madera. El arquitecto Robert Pohlitz diseñó el edificio al estilo gótico inglés. El castillo está situado en un gran parque con especies de árboles raros. Durante la era soviética se utilizó como granero. Hoy es un hotel y lugar de eventos. Anualmente se celebra el festival del castillo de Sangaste.",
      pt: "O castelo de Sangaste (também chamado Sagnitz) é uma mansão neogótica no sul da Estónia, construída entre 1873 e 1879 para o conde Friedrich von Berg. O castelo é conhecido pela sua torre de 50 metros de altura e pela sua rica decoração interior com troféus de caça e entalhes em madeira. O arquiteto Robert Pohlitz projetou o edifício no estilo gótico inglês. O castelo situa-se num grande parque com espécies arbóreas raras. Durante a era soviética, foi utilizado como celeiro. Hoje é um hotel e local de eventos. Anualmente, realiza-se a festa do castelo de Sangaste.",
      fr: "Le château de Sangaste (également appelé Sagnitz) est un manoir néogothique du sud de l'Estonie, construit entre 1873 et 1879 pour le comte Friedrich von Berg. Le château est réputé pour sa tour de 50 mètres de haut et sa riche décoration intérieure agrémentée de trophées de chasse et de sculptures sur bois. L'architecte Robert Pohlitz a conçu le bâtiment dans le style gothique anglais. Le château est situé dans un grand parc abritant des espèces d'arbres rares. Pendant l'ère soviétique, il a servi de grenier à grains. Aujourd'hui, c'est un hôtel et un lieu d'événements. Le festival du château de Sangaste a lieu chaque année.",
    },
