      de: ["Bauzeit des Schlosses dauerte von 1874 bis 1881", "Architekt Otto Pius Hippius entwarf das Gebäude", "Inspiration durch das britische Windsor Castle", "Graf von Berg züchtete hier die berühmte Sangaste-Roggensorte", "Das Schloss besaß 99 Zimmer (mehr waren dem Adel nicht erlaubt)", "Umgeben von einem Dendropark mit über 200 Baumarten"],
