      ro: ["Prima atestare documentară a moșiei datează din 1453", "Proprietatea a aparținut mult timp familiei von Baranoff", "Elemente neoclasice sunt vizibile în structurile administrative", "Clădirile economice au fost extinse major în secolul al XIX-lea", "Utilizat pentru agricultura colectivă începând cu anul 1940", "În prezent este un sit istoric cu ruine și valoare patrimonială"],
