      pt: "O castelo fundado no século XIII foi remodelado várias vezes ao longo da história e foi temporariamente a residência do rei livônio Magnus.",
      fr: "Le château fondé au XIIIe siècle fut transformé à plusieurs reprises au cours de l'histoire et fut temporairement la résidence du roi de Livonie, Magnus.",
