      ro: ["Prima fortăreață de piatră a fost ridicată în 1272", "A fost sediul Ducelui Magnus, singurul rege al Livoniei", "Transformarea în palat rococo a avut loc în anii 1770", "Castelul a ars aproape complet în iulie 1941", "Biserica Sf. Nicolae este integrată în structura fortificată", "Põltsamaa este renumit pentru producția tradițională de vin"],
