      ro: ["Fondat în anul 1342 de către Burchard von Dreileben.", "A servit drept avanpost strategic la granița cu Rusia.", "Centru european de pelerinaj după miracolul crucii din 1353.", "Distrus aproape total în 1702, în timpul Războiului Nordului.", "Pelerinii primeau indulgențe papale pentru vizitarea capelei.", "Zidurile de apărare aveau o grosime de până la 4 metri."],
      en: ["Founded in 1342 by Landmeister Burchard von Dreileben.", "Served as a key defensive outpost on the Russian border.", "A major pilgrimage site following the 1353 miracle cross.", "Russian forces destroyed the castle in 1702 during a war.", "Medieval pilgrims received papal indulgences for visiting.", "The massive defensive walls reached a thickness of 4 meters."],
