      pt: ["Primeira menção no ano 1241.", "A torre da igreja tem 50 metros de altura.", "A nave tem 40 metros de comprimento.", "A renovação de 1990 custou 1 milhão de euros.", "O cemitério abrange 1,5 hectares.", "O retábulo foi pintado em 1870."],
