      de: ["13. Jahrhundert", "St. Nikolai", "Harjumaa", "Historische Architektur"],
      hu: ["13. század", "Szent Miklós", "Harjumaa", "Történelmi építészet"],
      ro: ["Secolul al XIII-lea", "Sf. Nicolae", "Harjumaa", "Arhitectură istorică"],
      en: ["13th century", "St. Nicholas", "Harjumaa", "Historic architecture"],
      es: ["Siglo XIII", "San Nicolás", "Harjumaa", "Arquitectura histórica"],
      pt: ["Século XIII", "São Nicolau", "Harjumaa", "Arquitetura histórica"],
