    imageHint: "Kose church",
    descriptionAdvanced: {
      de: "Die St.-Nikolaus-Kirche in Kose ist eine der ältesten Steinkirchen im Kreis Harju, deren Fundamente bis ins 14. Jahrhundert zurückreichen. Das Gebäude wurde im Laufe der Jahrhunderte mehrfach rekonstruiert, insbesondere nachdem es während des Livländischen Krieges im Jahr 1560 und bei späteren Konflikten zerstört worden war. Das heutige Erscheinungsbild der Kirche ist geprägt von ihren massiven Steinmauern und einem hohen, schlanken Turm, der während einer umfassenden Renovierung im Jahr 1890 hinzugefügt wurde. Im Inneren beherbergt die Kirche mehrere wertvolle Kunstwerke, darunter einen Barockaltar, der 1630 von Tobias Heintze geschaffen wurde, sowie eine historische Kanzel. Die Kirche von Kose diente über Jahrhunderte hinweg als wichtiges soziales und Bildungszentrum für die umliegenden Pfarreien. Ihre beständige Präsenz spiegelt die langfristige Stabilität des christlichen Glaubens im ländlichen Estland trotz der häufigen Umbrüche in der baltischen Geschichte wider.",
      hu: "A kosei Szent Miklós-templom Harju megye egyik legrégebbi kőtemploma, alapjai a 14. századra nyúlnak vissza. Az épületet az évszázadok során többször is átépítették, különösen azután, hogy 1560-ban a livóniai háború alatt, majd a későbbi konfliktusokban elpusztult. A templom jelenlegi megjelenését masszív kőfalai és egy magas, karcsú torony határozza meg, amelyet egy 1890-es nagy felújítás során adtak hozzá. Odabent a templom számos értékes műalkotást őriz, köztük egy Tobias Heintze által 1630-ban készített barokk oltárt és egy történelmi szószéket. A kosei templom évszázadokon át fontos társadalmi és oktatási központként szolgált a környező egyházközségek számára. Tartós jelenléte a keresztény hit hosszú távú stabilitását tükrözi a vidéki Észtországban, a balti történelem gyakori megrázkódtatásai ellenére.",
      ro: "Biserica Sfântul Nicolae din Kose este una dintre cele mai vechi biserici de piatră din regiunea județului Harju, cu fundații ce datează din secolul al XIV-lea. Clădirea a suferit mai multe reconstrucții de-a lungul secolelor, în special după ce a fost distrusă în timpul Războiului Livonian în 1560 și din nou în timpul conflictelor ulterioare. Aspectul actual al bisericii este caracterizat de zidurile sale masive de piatră și de o turlă înaltă și subțire care a fost adăugată în timpul unei renovări majore în 1890. În interior, biserica adăpostește mai multe piese de artă valoroase, inclusiv un altar baroc creat de Tobias Heintze în 1630 și un amvon istoric. Biserica din Kose a servit ca un important centru social și educațional pentru parohiile din jur timp de sute de ani. Prezența sa durabilă reflectă stabilitatea pe termen lung a credinței creștine în mediul rural estonian, în ciuda deselor răsturnări de situație din istoria Balticii.",
      en: "St. Nicholas' Church in Kose is one of the oldest stone churches in the Harju County region, with its foundations dating back to the 14th century. The building has undergone several reconstructions over the centuries, particularly after being destroyed during the Livonian War in 1560 and again during subsequent conflicts. The church's current appearance is characterized by its massive stone walls and a tall, slender spire that was added during a major renovation in 1890. Inside, the church houses several valuable pieces of art, including a Baroque altar created by Tobias Heintze in 1630 and a historical pulpit. Kose Church served as an important social and educational center for the surrounding parishes for hundreds of years. Its enduring presence reflects the long-term stability of the Christian faith in rural Estonia despite the frequent upheavals of Baltic history.",
      es: "La iglesia de Kose es un templo medieval situado en el pueblo de Kose, en Estonia. Fue construida en el siglo XIII y es una de las iglesias de piedra más antiguas del país. La iglesia presenta un estilo románico-gótico y cuenta con una maciza torre occidental. El interior contiene valiosos frescos del siglo XIV. Durante la Reforma la iglesia estuvo en riesgo de ruina, pero fue restaurada en el siglo XIX. Está rodeada por una antigua muralla y hoy funciona como museo y ocasionalmente para servicios religiosos. Es un destino popular para el turismo histórico.",
      pt: "A Igreja de Kose é uma igreja medieval na aldeia de Kose, na Estónia. Foi construída no século XIII e é uma das igrejas de pedra mais antigas do país. A igreja é de estilo românico-gótico e possui uma torre ocidental maciça. O interior contém frescos valiosos do século XIV. Durante a Reforma, a igreja esteve em decadência, mas foi restaurada no século XIX. Está rodeada por uma antiga muralha e serve hoje como museu e ocasionalmente para serviços religiosos. A igreja é um destino popular para turistas de história.",
      fr: "L'église de Kose est une église médiévale située dans le village de Kose en Estonie. Elle a été construite au XIIIe siècle et est l'une des plus anciennes églises en pierre du pays. L'église est de style romano-gothique et possède un massif clocher occidental. L'intérieur contient des fresques précieuses du XIVe siècle. L'église est tombée en décrépitude pendant la Réforme, mais a été restaurée au XIXe siècle. Elle est entourée d'un vieux rempart et sert aujourd'hui de musée et occasionnellement pour des cultes. L'église est une destination prisée des amateurs d'histoire.",
    },
    factsAdvanced: {
      de: ["Die Kirche wurde wahrscheinlich um 1370 aus Stein errichtet.", "Im Jahr 1560 wurde sie von Truppen Iwans des Schrecklichen niedergebrannt.", "Der Barockaltar wurde 1630 vom Meister Tobias Heintze geschnitzt.", "Der heutige neugotische Turm erreicht eine Höhe von über 50 Metern.", "Die Kirche besitzt eine der ältesten erhaltenen Kirchenladen in Estland.", "Otto von Kotzebue, der berühmte Entdecker, ist auf dem Kirchhof begraben."],
      hu: ["A templom valószínűleg 1370 körül épült kőből.", "1560-ban Rettegett Iván csapatai felégették az épületet.", "A barokk oltárt 1630-ban Tobias Heintze mester faragta.", "A jelenlegi neogótikus torony több mint 50 méter magas.", "A templom rendelkezik az egyik legrégebbi észt templomi persellyel.", "Otto von Kotzebue, a híres felfedező a templomkertben nyugszik."],
      ro: ["Biserica a fost probabil ridicată din piatră în jurul anului 1370.", "În 1560, a fost incendiată de trupele lui Ivan cel Groaznic.", "Altarul baroc a fost sculptat în 1630 de maestrul Tobias Heintze.", "Turla actuală în stil neogotic are o înălțime de peste 50 de metri.", "Biserica deține una dintre cele mai vechi lăzi de biserică din Estonia.", "Celebrul navigator Otto von Kotzebue este înmormântat în cimitirul bisericii."],
      en: ["The stone church was likely established around the year 1370.", "It was burned down during the Livonian War by Russian troops in 1560.", "The ornate Baroque altar was crafted by Tobias Heintze in 1630.", "The modern spire, added in 1890, stands over 50 meters tall.", "The church yard is the final resting place of explorer Otto von Kotzebue.", "It houses one of the oldest church offering boxes preserved in Estonia."],
      es: ["Construida en el siglo XIII (hacia 1270).", "La torre tiene 30 metros de altura.", "Los frescos datan de 1340.", "Los muros tienen 1,5 metros de espesor.", "Restaurada en 1850.", "La nave tiene 25 metros de largo."],
      pt: ["Construída no século XIII (cerca de 1270).", "A torre tem 30 metros de altura.", "Os frescos datam de 1340.", "As paredes têm 1,5 metros de espessura.", "Restaurada em 1850.", "A nave tem 25 metros de comprimento."],
      fr: ["Construite au XIIIe siècle (vers 1270).", "La tour mesure 30 mètres de haut.", "Les fresques datent de 1340.", "Les murs font 1,5 mètre d'épaisseur.", "Restaurée en 1850.", "La nef mesure 25 mètres de long."],
    },
