    imageHint: "Malla manor",
    descriptionAdvanced: {
      de: "Das Gutshaus Malla, erstmals im Jahr 1443 urkundlich erwähnt, liegt im Kreis Lääne-Viru im Norden Estlands. Im Laufe seiner jahrhundertelangen Geschichte wechselte das Anwesen häufig die Besitzer, darunter einflussreiche Familien wie die von Loewenwolde und von Wrangell. Das ursprüngliche steinerne Hauptgebäude wurde im späten 18. Jahrhundert im klassizistischen Stil errichtet, erlitt jedoch durch schwere Brände in den Jahren 1880 und 1918 erhebliche Schäden. Die heutige Bausubstanz besteht größtenteils aus den Überresten des im 19. Jahrhundert umgebauten Herrenhauses. Trotz des teilweisen Verfalls spiegeln die Ruinen und die erhaltenen Nebengebäude die einstige wirtschaftliche und soziale Bedeutung der baltischen Adelskultur wider. Das Gut war über lange Zeit ein zentraler Knotenpunkt für die regionale Landwirtschaft und die lokale Verwaltung. Heute dient das Areal als historisches Zeugnis für die Entwicklung der estnischen Architekturlandschaft und zieht Geschichtsinteressierte an, die die Atmosphäre vergangener Jahrhunderte suchen.",
      hu: "A Malla udvarház, amelyet először 1443-ban említenek az oklevelek, Észtország északi részén, Lääne-Viru megyében található. Hosszú történelme során az ingatlan számos neves balti német család, köztük a von Loewenwolde és a von Wrangell családok tulajdonában volt. A főépületet eredetileg a 18. század végén emelték klasszicista stílusban, de az épületet több súlyos tűzvész is sújtotta, különösen 1880-ban és 1918-ban. A mai épületegyüttes nagy része a 19. századi átépítések és a későbbi romos állapotok elegyét mutatja. Annak ellenére, hogy az épület egy része romos, a megmaradt gazdasági épületek és a falak hűen tükrözik a balti nemesi kultúra egykori gazdagságát és társadalmi súlyát. A birtok évszázadokon át a környék mezőgazdasági központjaként és közigazgatási egységeként működött. Napjainkban a terület fontos történelmi emlékhely, amely bepillantást enged az észtországi kúriák építészetébe és a nemesi életmód alakulásába.",
      ro: "Conacul Malla, menționat pentru prima dată în documente în anul 1443, este situat în județul Lääne-Viru din nordul Estoniei. De-a lungul istoriei sale îndelungate, proprietatea a aparținut mai multor familii nobiliare influente, inclusiv familiile von Loewenwolde și von Wrangell. Clădirea principală originală a fost construită la sfârșitul secolului al XVIII-lea în stil clasicist, însă a suferit daune majore în urma unor incendii devastatoare în anii 1880 și 1918. Structura actuală reflectă în mare parte reconstrucțiile din secolul al XIX-lea, păstrând elemente arhitecturale deosebite în ciuda stării parțiale de degradare. Conacul a servit timp de secole ca centru economic și administrativ important pentru regiunea înconjurătoare, fiind un pilon al culturii nobiliare germano-baltice. Ruinele impunătoare și clădirile anexe rămase sunt mărturii ale opulenței de odinioară și ale evoluției stilurilor arhitecturale din Estonia. Astăzi, situl reprezintă un punct de interes pentru cercetătorii istoriei locale și pentru turiștii pasionați de patrimoniul nobiliar european.",
      en: "Malla Manor, first documented in 1443, is situated in Lääne-Viru County in northern Estonia. Throughout its long history, the estate was owned by several prominent Baltic German families, including the von Loewenwoldes and the von Wrangells. The main stone building was originally constructed in the late 18th century in the Classicist style, but it suffered significant damage during devastating fires in 1880 and 1918. Much of the current structure dates back to the 19th-century renovations, showcasing the architectural preferences of the local nobility. Despite its partially ruined state, the manor and its surviving outbuildings remain a testament to the economic and social importance of the Baltic aristocratic culture. For centuries, the estate functioned as a major agricultural hub and administrative center for the surrounding region. Today, the site serves as an evocative historical monument, offering insights into the development of Estonian manor architecture and the lifestyle of the landed gentry.",
      es: "La mansión de Malla es una casa señorial histórica en el pueblo de Malla, en el norte de Estonia. Fue construida en el siglo XVII y reformada en estilo barroco en el siglo XVIII. El edificio principal es una construcción de piedra de dos plantas con un alto tejado a cuatro aguas. La propiedad perteneció a la familia von Tiesenhausen. Tras la expropiación en 1919, se utilizó como escuela. Hoy es una residencia privada, pero se puede visitar por fuera. El parque de la mansión está asilvestrado, pero aún es reconocible.",
      pt: "A casa senhorial de Malla é um solar histórico na aldeia de Malla, no norte da Estônia. Foi construída no século XVII e remodelada em estilo barroco no século XVIII. O edifício principal é uma construção de pedra de dois andares com um alto telhado de quatro águas. A propriedade pertenceu à família von Tiesenhausen. Após a expropriação em 1919, foi utilizada como escola. Hoje é uma residência privada, mas pode ser visitada por fora. O parque do solar está selvagem, mas ainda é reconhecível.",
      fr: "Le manoir de Malla est une maison seigneuriale historique située dans le village de Malla, dans le nord de l'Estonie. Il fut construit au XVIIe siècle et transformé en style baroque au XVIIIe siècle. Le bâtiment principal est une construction en pierre de deux étages avec un haut toit en croupe. Le domaine appartenait à la famille von Tiesenhausen. Après l'expropriation en 1919, il servit d'école. Aujourd'hui, c'est une résidence privée, mais visitable de l'extérieur. Le parc du manoir est retourné à l'état sauvage, mais reste reconnaissable.",
    },
